"use strict";(globalThis.webpackChunkmy_website||=[]).push([[32274],{87273(e){e.exports=JSON.parse('{"slug":"untyped-plutus-core-uplc","title":"Untyped Plutus Core (UPLC)","short":"The low-level \u201cmachine language\u201d that is executed on-chain by Cardano nodes during transaction validation.","category":"smart-contracts","aliases":["UPLC"],"mentalModel":null,"related":["plutus","plutus-core","aiken","smart-contract"],"sources":[],"link":null,"level":"advanced","body":"The low-level \u201cmachine language\u201d that is executed on-chain by Cardano nodes during transaction validation. Developers do not write UPLC directly. Instead, smart contracts are written in higher-level languages such as Plinth or Aiken, which are then compiled down to UPLC. Every smart contract language on Cardano ultimately targets UPLC as the common execution format."}')}}]);